"""Complete public destinations. Authored copy; no invented users or results."""
from home import icon

def render_pages(t,a,button,invitation):
    def intro(kicker,title,body=''):
        return f'<section class="page-intro wrap"><p class="eyebrow">{kicker}</p><h1>{title}</h1>{f"<p class=\"lead\">{body}</p>" if body else ""}</section>'
    def paper(label,body):
        return f'<div class="mini-paper"><span>{label}</span>{body}</div>'
    def spread(title,body,visual,link=''):
        return f'<section class="feature-spread"><div class="feature-copy"><h2>{title}</h2><p>{body}</p>{link}</div><div class="feature-visual">{visual}</div></section>'
    pages=[]
    how=intro(t('如何使用','How it works'),t('留下表达，<br>接上每一次思考。','Keep your words.<br>Build on your thinking.'),t('从你已经在进行的 AI 对话开始。日常记录不必变成一份额外的整理工作。','Start with the AI conversations you already have. Keeping a record should fit into the work you are already doing.'))
    how+=f'<p class="wrap product-scope-note">{t("下面说明已确定的完整体验。当前从 Chrome / ChatGPT 内测开始；AI 整理、真实连接和云同步仍在开发。", "This describes the approved complete experience. The current beta starts with Chrome / ChatGPT; AI organization, real connections and cloud sync are still in development.")} {a("status.html",t("当前可用范围","Current availability"))}</p>'
    steps=[
      (t('安装后，选择保存哪些输入。','Install, then choose to keep your inputs.'),t('获邀后按说明安装桌面 Chrome 测试版。开启保存后，PAIA 留下支持的 ChatGPT 页面中已发送的用户文字。你可以暂停；导入官方历史文件是单独的主动操作。','Invited participants follow the setup instructions for the desktop Chrome beta. Once capture is enabled, PAIA keeps sent user text from supported ChatGPT pages. You can pause it. Importing an official history file is a separate action.'),paper('ChatGPT',t('“第一版应该帮助创作者找回素材，而不是生成更多内容。”','“The first release should help creators find material, not generate more.”'))),
      (t('找回一句话，也找回它的位置。','Find a sentence, and where it belongs.'),t('按来源、项目和会话浏览，或用关键词找到具体输入。连续阅读并修订工作文字；原始记录仍可核对。重复指令可以从阅读中暂时过滤，原文并未被删除。','Browse sources, projects and conversations, or search for a particular input. Read continuously and revise the working text while keeping the original available. Repeated instructions can be filtered from reading without deleting the source.'),paper(t('原始表达','Original input'),t('“先看看哪些功能可能有价值。”','“Explore which features could be useful.”'))+paper(t('工作版本','Working version'),t('“先验证素材找回，暂不做多人协作。”','“Validate retrieval first. Leave collaboration out.”'))),
      (t('把常用表达放在手边。','Keep useful phrases within reach.'),t('在自己的提示词库中修改、固定和排列常用说法。下一次用 AI 时，点选填入输入框，再由你发送；不用从旧会话中反复复制，也不会自动替你发问。','Edit, pin and arrange useful phrases in your personal prompt library. Next time you use AI, choose one to fill the composer, then send it yourself. No repeated search through old chats, and no automatic sending.'),paper(t('个人提示词','Personal prompt'),t('“给出最强的反例和遗漏变量。”','“Give the strongest counterexample and missing variables.”'))),
      (t('围绕自己的主题继续想。','Keep thinking around your own topics.'),t('用个人主题和章节把跨会话的相关内容放在一起。人工组织始终由你决定；计划中的 AI 整理提供原话优先、平衡整理和更加概括三种阅读方式，不覆盖原文。','Bring related material from different conversations into personal topics and sections. You remain in charge of the structure. Planned AI organization offers Original-first, Balanced and More concise reading views without overwriting your words.'),paper(t('个人主题 / 产品的第一步','Personal topic / A product’s first step'),t('探索与取舍<br>保留的决定<br>仍待验证的问题','Exploration and trade-offs<br>Decisions retained<br>Questions still to test'))),
      (t('设置范围，让 AI 按需接上。','Set the scope. Let a connected AI pick it up.'),t('在我的信息、我的规则、我的现在中管理独立内容，在我的输入中选择允许读取的主题。真实连接可用后，获准的 AI 可在需要时读取；日常不必重新选材料或制作 Context 包。所有访问默认关闭，也可以随时暂停。','Manage independent items in My Information, My Rules and My Now, and choose allowed topics in My Inputs. Once real connections are available, authorized AI can read when needed. You will not need to assemble a Context packet for each task. Access starts off and can be paused.'),paper(t('四卡 Context · 连接规划中','Four-card Context · Connections planned'),t('我的信息 / 我的规则<br>我的现在 / 我的输入','My Information / My Rules<br>My Now / My Inputs')))
    ]
    how+='<div class="wrap">'+''.join(spread(h,p,v) for h,p,v in steps)+'</div>'+invitation()
    pages.append(('how-it-works.html',t('PAIA — 如何使用','PAIA — How it works'),t('从安装与保存，到找回输入、复用提示词、个人主题和四卡 Context。','From setup and capture to retrieval, personal prompts, your topics and four-card Context.'),how))
    use=intro(t('使用场景','Use cases'),t('长期在做的事，<br>不该反复从零开始。','For work that lasts<br>beyond one conversation.'),t('项目、研究、决策。先把自己的积累找回来，再决定哪些可以继续使用。','Projects, research and decisions. Recover what you have already worked out, then decide what to use again.'))
    cases=[
       (t('继续一个项目。','Continue a project.'),t('找回既定目标、用户和边界，再讨论下一版。先前否定的方案不必反复解释。','Recover the goal, audience and boundaries before discussing the next version. You should not have to explain rejected options again.'),paper(t('带上','Bring forward'),t('目标、用户、范围、已确认的决定。','Goal, audience, scope and confirmed decisions.'))+paper(t('新的任务','Next task'),t('“在这些边界内，评估下一版。”','“Review the next version within these boundaries.”'))),
       (t('接上一个研究问题。','Build on a research question.'),t('把先前的问题、假设和未解之处找回来。保留引用与自己的判断之间的区别。','Recover earlier questions, assumptions and open problems. Keep quoted material distinct from your own conclusions.'),paper(t('先前留下的问题','Earlier question'),t('这个结论依赖哪些假设？','Which assumptions does this conclusion depend on?'))+paper(t('新的任务','Next task'),t('“只讨论这些假设改变后会发生什么。”','“Focus on what changes when these assumptions change.”'))),
       (t('更新一次重要选择。','Revisit a decision.'),t('比较当时的限制和现在的新信息。过去的表达是有时间背景的材料，不是永久不变的个人画像。','Compare earlier constraints with new information. Past expressions are evidence from a point in time, not a permanent profile.'),paper(t('之前的约束','Earlier constraints'),t('地点、工作内容与学习空间。','Location, day-to-day work and room to learn.'))+paper(t('新的任务','Next task'),t('“结合更新后的约束，重新比较这两个选项。”','“Compare these two options using the updated constraints.”')))
    ]
    use+='<div class="wrap">'+''.join(spread(h,p,v,a('demo.html',t('体验示例','Explore an example'),'text-link')) for h,p,v in cases)+'</div>'+invitation()
    pages.append(('use-cases.html',t('PAIA — 使用场景','PAIA — Use cases'),t('让长期项目、研究与决策接上已有积累。','Carry existing context into projects, research and decisions.'),use))
    articles=[
      ('context','collect',t('聊天历史之外，还需要什么？','What do you need beyond chat history?'),t('保留说过的话，也保留管理和再次使用它们的能力。','Keep what you said, and the ability to manage and use it again.'),[
        (t('找到原话，而不是重新猜一次。','Return to your words.'),t('一次对话包含问题、试探、引用和后来放弃的方向。PAIA 从你自己的输入出发，保留来源与时间，让你回到具体的一句话，修改工作版本。它不把一份摘要当作所有原话的替代品。','A conversation contains questions, experiments, quotations and abandoned directions. PAIA starts from your own inputs and keeps their source and time. Return to a particular sentence and revise its working version. A summary does not replace the underlying words.')),
        (t('对话会结束，主题可以继续。','A conversation ends. A topic can continue.'),t('同一个项目可能分散在许多会话里。个人主题与章节把它们放在一处，你的命名、排列、修改和排除始终优先。AI 整理是在这些内容之上的阅读帮助。','A project may run through many conversations. Personal topics and sections bring it together, with your names, order, edits and exclusions taking priority. AI organization is a reading aid over that material.')),
        (t('保存与允许 AI 读取，是两次选择。','Keeping and allowing access are separate choices.'),t('Context 的我的信息、我的规则、我的现在和我的输入，把背景与允许范围放在明处。连接可用后，AI 才能按获准范围按需读取；安装或保存本身不会自动开放整个档案。','My Information, My Rules, My Now and My Inputs make your background and reading permissions explicit. Once connections are available, AI can read on demand within the allowed scope. Installation or capture does not open the whole archive.'))]),
      ('beliefs','connect',t('发给 AI 的，不一定是你的观点。','Not every input is a belief.'),t('引用、试探和任务指令，都需要保留各自的语境。','Quotations, experiments and instructions need their own context.'),[
        (t('输入里有多种声音。','An input can contain several voices.'),t('你可能把一份岗位说明、一段待改写文字或一个假设发给 AI。这能证明你发送过这些文字，但不能证明每句话都是你的长期立场。','You might send AI a job description, a draft to rewrite or a hypothetical argument. The record establishes that you sent those words. It does not establish that every sentence is a lasting belief.')),
        (t('整理要能够回到来源。','Organization must stay traceable.'),t('原话优先、平衡整理和更加概括，改变的是衍生阅读方式。无论哪一种，都需要保留条件、立场与不确定性，并能回到来源核对，不能替你发明观点。真实 AI 整理服务仍在开发。','Original-first, Balanced and More concise change the derived reading view. Each must preserve conditions, perspective and uncertainty and remain traceable to sources. None may invent a position for you. The live AI organization service is still in development.')),
        (t('当前选择仍然属于你。','The current choice still belongs to you.'),t('过去说过的话不一定适用于现在。你可以修改工作内容、管理主题和关闭 AI 访问，不让一段旧表达自动变成对未来行为的授权。','Past words may no longer apply. You can revise working content, manage topics and close AI access. A historical expression is not automatic permission for future actions.'))]),
      ('reuse','reuse',t('把自己的常用说法，留在手边。','Keep your own useful phrases close.'),t('不用一次次翻旧聊天，也不替你自动发送。','Less searching through old chats. Sending stays with you.'),[
        (t('复用已经适合自己的表达。','Reuse expressions that suit your work.'),t('反复使用的分析要求、写作标准或追问方式，是你自己的工作习惯。PAIA 的个人提示词围绕这些真实表达组织，相似说法放在一起，不需要先挑选一套公共模板。','Repeated analysis requests, writing standards and follow-up questions are part of your own practice. PAIA organizes personal prompts around those expressions and related wordings. You do not need to begin with a public template collection.')),
        (t('需要时修改，随时调整顺序。','Edit and arrange them as your work changes.'),t('你可以改写、固定、排序或隐藏自己的提示词。下一次点选填入 AI 输入框，检查和修改后再发送。提示词库不会替你点击发送，也不会把旧指令当作新的执行许可。','Rewrite, pin, reorder or hide your prompts. Next time, choose one to fill the AI composer, review or edit it, then send. The library does not send on your behalf or turn an old instruction into fresh execution authority.')),
        (t('常用指令与个人背景，各有位置。','Useful instructions and personal background have their own place.'),t('个人提示词帮助你更快表达当前请求；四卡 Context 管理你允许连接的 AI 按需了解的背景和主题。它们互相补充，不要求你每次复制整段历史。真实 Context 连接仍在开发。','Personal prompts help you express the current request. Four-card Context manages the background and topics a connected AI may read when needed. They complement one another without asking you to copy an entire history. Real Context connections are still in development.'))])
    ]
    blog=intro(t('产品文章','Product notes'),t('关于自己的表达，<br>值得保留的几个原则。','A few principles for<br>keeping your words useful.'))
    blog+='<div class="journal-list wrap">'+''.join(a('article-'+slug+'.html',icon(ico)+f'<div><h2>{title}</h2><p>{summary}</p></div>'+icon('arrow','mini-icon'),'journal-item') for slug,ico,title,summary,_ in articles)+'</div>'
    pages.append(('blog.html',t('PAIA — 产品文章','PAIA — Product notes'),t('关于上下文、个人表达与复用的产品思考。','Product notes on personal expression, context and reuse.'),blog))
    for slug,ico,title,summary,sections in articles:
        body=intro(t('产品文章','Product notes'),title,summary)
        body+='<article class="essay prose wrap">'+''.join(f'<section><h2>{h}</h2><p>{p}</p></section>' for h,p in sections)+f'<nav class="essay-nav">{a("blog.html",t("返回文章","Back to notes"),"text-link")}{a("demo.html",t("体验产品示例","Try the product example"),"text-link")}</nav></article>'
        pages.append(('article-'+slug+'.html','PAIA — '+title,summary,body))
    return pages
